B.ana=new A.ra("scuba","\uc2a4\ucfe0\ubc84 \uba74\ucc45","\uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59 \ucc45\uc784 \uba74\ucc45 \ubc0f \uc704\ud5d8 \uc778\uc9c0\xb7\uc218\uc6a9 \ub3d9\uc758\uc11c","SCUBA DIVING LIABILITY RELEASE & ASSUMPTION OF RISK AGREEMENT","\ubcf8 \ub3d9\uc758\uc11c\ub294 APDI \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59 \uad50\uc721, \ud6c8\ub828 \ubc0f \uad00\ub828 \uc218\uc911\ud65c\ub3d9\uc5d0 \ucc38\uac00\ud558\ub294 \uc0ac\ub78c\uc774 \ud65c\ub3d9\uc758 \uc7a0\uc7ac\uc801 \uc704\ud5d8\uacfc \uc548\uc804\uc0c1 \uc758\ubb34\ub97c \ucda9\ubd84\ud788 \uc774\ud574\ud558\uace0, \uc790\ubc1c\uc801\uc73c\ub85c \ucc38\uac00\ud558\ub294\uc9c0 \ud655\uc778\ud558\uae30 \uc704\ud55c \ubb38\uc11c\uc785\ub2c8\ub2e4. \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \ubaa8\ub4e0 \uc870\ud56d\uc744 \uc8fc\uc758 \uae4a\uac8c \uc77d\uace0 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uae30\uc7ac\ud558\uc5ec \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.","\ubcf8 \ub3d9\uc758\uc11c\ub294 \ub2e4\uc774\ubc84 \uac74\uac15\uc9c4\uc220\uc11c, \uad50\uc721 \uc2e0\uccad\uc11c \ubc0f \uacfc\uc815\ubcc4 \uc548\uc804\uad50\uc721 \ud655\uc778\uc11c\ub97c \ub300\uccb4\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.",B.a0a,B.Yt)
B.a_w=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc774 \uc678\ubd80 \ud638\ud761 \uae30\uccb4\uc758 \uacf5\uae09 \uc5c6\uc774 \ud638\ud761\uc744 \uc77c\uc2dc\uc801\uc73c\ub85c \uc815\uc9c0\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc218\ud589\ud558\ub294 \uc218\uc911\ud65c\ub3d9\uc774\uba70, \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\uacfc\ub294 \ub2e4\ub978 \uace0\uc720\ud55c \uc704\ud5d8\uc774 \uc874\uc7ac\ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc704\ud5d8\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.YV=s(["\uc800\uc0b0\uc18c\uc99d(Hypoxia)\uc5d0 \ub530\ub978 \uc758\uc2dd \ubc0f \uc2e0\uccb4\uae30\ub2a5 \uc800\ud558","\uc800\uc0b0\uc18c\uc131 \uc758\uc2dd \uc18c\uc2e4(Blackout)\uacfc \uc6b4\ub3d9\uc870\uc808 \uc0c1\uc2e4(Loss of Motor Control)","\uacfc\ud638\ud761\uc73c\ub85c \uc778\ud55c \uc815\uc0c1\uc801\uc778 \ud638\ud761 \uc695\uad6c\uc758 \uc9c0\uc5f0 \ubc0f \uc704\ud5d8 \uc778\uc9c0 \ub2a5\ub825 \uac10\uc18c","\uadc0, \ubd80\ube44\ub3d9 \ubc0f \ud3d0\uc758 \uc555\ub825 \uc190\uc0c1","\uc218\uc911\uc5d0\uc11c\uc758 \ubc29\ud5a5\uac10\uac01 \uc0c1\uc2e4 \ubc0f \uc218\uba74 \ubcf5\uadc0\uc758 \uc5b4\ub824\uc6c0","\ud574\ub958, \ud30c\ub3c4, \uc218\uc628 \ubc0f \uc2dc\uc57c \ubcc0\ud654\uc5d0 \ub530\ub978 \uc704\ud5d8","\uc2e0\uccb4\uc801 \ud53c\ub85c, \uacf5\ud3ec, \uc2a4\ud2b8\ub808\uc2a4 \ubc0f \uac1c\uc778\uc758 \uac74\uac15 \uc0c1\ud0dc\uc5d0 \ub530\ub978 \uc704\ud5d8","\uc548\uc804\uc694\uc6d0\uc758 \uad6c\uc870 \ubc0f \uc751\uae09\uc758\ub8cc \uc870\uce58\uac00 \uc9c0\uc5f0\ub420 \uc218 \uc788\ub294 \uc704\ud5d8"],t.s)
B.amN=new A.e4("\uc81c2\uc870. \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \ud2b9\uc218 \uc704\ud5d8\uc5d0 \ub300\ud55c \uc778\uc9c0",B.a_w,B.YV)
B.a07=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59 \ucc38\uac00\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\ub294 \ubcf8\uc778\uc758 \uac74\uac15 \uc0c1\ud0dc\ub97c \uc815\ud655\ud558\uac8c \uace0\uc9c0\ud574\uc57c \ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ubcc4\ub3c4\uc758 \uac74\uac15\uc9c4\uc220\uc11c\uc5d0 \uc0ac\uc2e4\ub300\ub85c \uc751\ub2f5\ud558\uba70, \ud544\uc694\ud55c \uacbd\uc6b0 \uc758\ub8cc\uc804\ubb38\uac00\uc758 \ud3c9\uac00\ub97c \ubc1b\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uad50\uc721 \uc911 \uc5b4\uc9c0\ub7ec\uc6c0, \ud1b5\uc99d, \ube44\uc815\uc0c1\uc801\uc778 \ud53c\ub85c \ub610\ub294 \uae30\ud0c0 \uc774\uc0c1 \uc99d\uc0c1\uc774 \ubc1c\uc0dd\ud558\ub294 \uacbd\uc6b0 \uc989\uc2dc \ub2f4\ub2f9 \uac15\uc0ac\uc5d0\uac8c \uc54c\ub9ac\uace0 \ud65c\ub3d9\uc744 \uc911\ub2e8\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.amW=new A.e4("\uc81c3\uc870. \uac74\uac15 \uc0c1\ud0dc \ubc0f \ucc38\uac00 \uc801\ud569\uc131",B.a07,B.A)
B.Xb=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc5d0\uc11c \ubc84\ub514 \uc2dc\uc2a4\ud15c\uacfc \uc801\uc808\ud55c \uc548\uc804\uac10\ub3c5\uc774 \ud544\uc218\uc801\uc784\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uc758 \uc548\uc804\uc218\uce59\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.a0D=s(["\ub2e8\ub3c5 \ud504\ub9ac\ub2e4\uc774\ube59\uc744 \uc2e4\uc2dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uad50\uc721\uae30\uad00\uacfc \uac15\uc0ac\uac00 \uc9c0\uc815\ud55c \ubc84\ub514 \ubc0f \uc548\uc804\uad00\ub9ac \uccb4\uacc4\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.","\uacfc\ud638\ud761\uacfc \ubb34\ub9ac\ud55c \uc228\ucc38\uae30 \uc2dc\ub3c4\ub97c \ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uac1c\uc778\uc758 \ub2a5\ub825 \ubc0f \uad50\uc721 \ubc94\uc704\ub97c \ucd08\uacfc\ud558\ub294 \uc218\uc2ec\uc774\ub098 \uae30\ub85d\uc5d0 \ub3c4\uc804\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uac15\uc0ac\uac00 \uc2b9\uc778\ud558\uc9c0 \uc54a\uc740 \ud6c8\ub828\uc744 \uc784\uc758\ub85c \uc218\ud589\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\ub2e4\uc774\ube59 \uc804\ud6c4 \ud544\uc694\ud55c \uc548\uc804 \ud655\uc778 \ubc0f \uc758\uc0ac\uc18c\ud1b5 \uc808\ucc28\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.","\uc704\ud5d8\ud558\uac70\ub098 \ubd88\uc548\ud558\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uacbd\uc6b0 \uc989\uc2dc \ud65c\ub3d9 \uc911\ub2e8\uc744 \uc694\uccad\ud569\ub2c8\ub2e4."],t.s)
B.an0=new A.e4("\uc81c4\uc870. \ubc84\ub514 \uc2dc\uc2a4\ud15c \ubc0f \uc548\uc804\uad00\ub9ac",B.Xb,B.a0D)
B.a0I=s(["\ubcf8\uc778\uc740 APDI \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721\uacfc\uc815\uc774 \uc774\ub860\uad50\uc721, \uc81c\ud55c\uc218\uc5ed \ub610\ub294 \uc218\uc601\uc7a5 \ud6c8\ub828, \uac1c\ubc29\uc218\uc5ed \ud6c8\ub828 \ubc0f \uacfc\uc815\ubcc4 \ud3c9\uac00\ud65c\ub3d9\uc744 \ud3ec\ud568\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc815\ud574\uc9c4 \uad50\uc721\uacfc\uc815\uc5d0\uc11c \ub2f4\ub2f9 \uac15\uc0ac\uc758 \uc9c0\ub3c4\uc640 \uac10\ub3c5\uc5d0 \ub530\ub77c \ud65c\ub3d9\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uae30\ub85d\uc774\ub098 \uac1c\uc778\uc801 \uc131\ucde8\ub97c \uc704\ud574 \uc548\uc804\uc218\uce59\uc744 \uc704\ubc18\ud558\uc9c0 \uc54a\uc73c\uba70, \uc801\uc808\ud55c \uc548\uc804\uac10\ub3c5 \uc5c6\uc774 \uc228\ucc38\uae30 \ud6c8\ub828\uc744 \uc2e4\uc2dc\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.an3=new A.e4("\uc81c5\uc870. \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721\ud65c\ub3d9\uc758 \uc774\ud574",B.a0I,B.A)
B.ZF=s(["\ubcf8\uc778\uc740 APDI\uac00 \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721 \uae30\uc900 \ubc0f \uad50\uc721\uccb4\uacc4\ub97c \uc81c\uacf5\ud558\ub294 \uc804\ubb38\ub2e8\uccb4\uc774\uba70, \uac1c\ubcc4 \uad50\uc721\uae30\uad00\uacfc \uac15\uc0ac\ub294 \ub3c5\ub9bd\uc801\uc73c\ub85c \ud65c\ub3d9\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub2e4\ub9cc \uac01 \uae30\uad00 \ubc0f \uac15\uc0ac\uc758 \uad6c\uccb4\uc801\uc778 \ubc95\uc801 \ucc45\uc784\uc740 \uc2e4\uc81c \uc6b4\uc601\uad00\uacc4, \uad00\ub9ac\xb7\uac10\ub3c5\uad00\uacc4 \ubc0f \uad00\ub828 \ubc95\ub839\uc5d0 \ub530\ub77c \uacb0\uc815\ub428\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.an2=new A.e4("\uc81c6\uc870. \uad50\uc721\uae30\uad00\uacfc APDI\uc758 \uad00\uacc4",B.ZF,B.A)
B.a0c=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \uc7a0\uc7ac\uc801\uc778 \uc704\ud5d8\uacfc \uc548\uc804\uc218\uce59\uc5d0 \ub300\ud55c \uc124\uba85\uc744 \ucda9\ubd84\ud788 \ub4e4\uc5c8\uc73c\uba70, \uc774\ub97c \uc774\ud574\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc790\ubc1c\uc801\uc73c\ub85c \uad50\uc721 \ubc0f \ud6c8\ub828\uc5d0 \ucc38\uac00\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc801\uc808\ud55c \uad50\uc721\uacfc \uc548\uc804\uac10\ub3c5\uc774 \uc81c\uacf5\ub418\ub354\ub77c\ub3c4 \uc218\uc911\ud65c\ub3d9\uc5d0 \ub530\ub974\ub294 \ubaa8\ub4e0 \uc704\ud5d8\uc744 \uc644\uc804\ud788 \uc81c\uac70\ud560 \uc218 \uc5c6\uc74c\uc744 \uc778\uc815\ud569\ub2c8\ub2e4.","\ub610\ud55c \ubcf8\uc778\uc758 \uc548\uc804\uc218\uce59 \uc704\ubc18\uc774\ub098 \ubb34\ub9ac\ud55c \ud65c\ub3d9\uc774 \uc0ac\uace0 \uc704\ud5d8\uc744 \ub192\uc77c \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.an7=new A.e4("\uc81c7\uc870. \uc790\ubc1c\uc801 \ucc38\uac00 \ubc0f \uc704\ud5d8 \uc218\uc6a9",B.a0c,B.A)
B.Zm=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \ubcf8\uc9c8\uc801\uc778 \uc704\ud5d8\uc744 \uc778\uc9c0\ud558\uace0 \uad00\uacc4 \ubc95\ub839\uc5d0\uc11c \ud5c8\uc6a9\ud558\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc774\ub7ec\ud55c \uc704\ud5d8\uc758 \ubc1c\uc0dd \uac00\ub2a5\uc131\uc744 \uc218\uc6a9\ud569\ub2c8\ub2e4.","\uadf8\ub7ec\ub098 \ubcf8 \ub3d9\uc758\uc11c\ub294 APDI, \uad50\uc721\uae30\uad00, \uac15\uc0ac \ubc0f \uad00\ub828\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc5d0 \ub530\ub978 \ubc95\uc801 \ucc45\uc784\uc744 \uc77c\uad04\uc801\uc73c\ub85c \uba74\uc81c\ud558\uac70\ub098 \ucc38\uac00\uc790\uc758 \uc815\ub2f9\ud55c \ubc95\uc801 \uad8c\ub9ac\ub97c \ud3ec\uae30\ud558\ub294 \uac83\uc73c\ub85c \ud574\uc11d\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc0ac\uace0 \ubc1c\uc0dd \uc2dc \ucc45\uc784\uc758 \uc720\ubb34 \ubc0f \ubc94\uc704\ub294 \uad6c\uccb4\uc801\uc778 \uc0ac\uace0 \uacbd\uc704\uc640 \uad00\uacc4 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.an_=new A.e4("\uc81c8\uc870. \ucc45\uc784 \uba74\ucc45\uc758 \ubc94\uc704",B.Zm,B.A)
B.Yv=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59 \uc911 \uc758\uc2dd \uc18c\uc2e4 \ub610\ub294 \uae30\ud0c0 \uc751\uae09\uc0c1\ud669\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc751\uae09\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uad50\uc721\uae30\uad00, \ub2f4\ub2f9 \uac15\uc0ac \ub610\ub294 \uc548\uc804\uc694\uc6d0\uc774 \uad6c\uc870 \uc694\uccad, \uc751\uae09\ucc98\uce58 \ubc0f \uc758\ub8cc\uae30\uad00 \uc774\uc1a1\uc744 \uc704\ud55c \uc870\uce58\ub97c \uc218\ud589\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud558\uace0 \uc774\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4."],t.s)
B.an6=new A.e4("\uc81c9\uc870. \uc751\uae09\uc0c1\ud669 \ubc0f \uad6c\uc870 \ud611\uc870",B.Yv,B.A)
B.a0o=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \uace0\uc720\ud55c \uc704\ud5d8\uacfc \uc548\uc804\uc218\uce59\uc744 \ucda9\ubd84\ud788 \uc774\ud574\ud558\uc600\uc73c\uba70, \ubcf8 \ub3d9\uc758\uc11c\uc758 \ubaa8\ub4e0 \uc870\ud56d\uc744 \uc77d\uace0 \uc124\uba85\uc744 \uc694\uccad\ud560 \uae30\ud68c\ub97c \uac00\uc84c\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc5b4\ub5a0\ud55c \uac15\uc694 \uc5c6\uc774 \uc790\ubc1c\uc801\uc73c\ub85c APDI \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721 \ubc0f \ud6c8\ub828\uc5d0 \ucc38\uac00\ud560 \uac83\uc744 \ud655\uc778\ud558\uace0 \uc11c\uba85\ud569\ub2c8\ub2e4."],t.s)
B.amQ=new A.e4("\uc81c10\uc870. \ucd5c\uc885 \ud655\uc778",B.a0o,B.A)
B.a0b=s([B.amN,B.amW,B.an0,B.an3,B.an2,B.an7,B.an_,B.an6,B.amQ],t.H9)
B.amF=new A.hi("risk","\ube14\ub799\uc544\uc6c3\xb7\uc800\uc0b0\uc18c\uc99d \ub4f1 \ud504\ub9ac\ub2e4\uc774\ube59 \uace0\uc720 \uc704\ud5d8\uc744 \uc778\uc9c0\ud558\uace0 \uc218\uc6a9\ud569\ub2c8\ub2e4.")
B.amE=new A.hi("buddy","\ub2e8\ub3c5 \ud504\ub9ac\ub2e4\uc774\ube59 \uae08\uc9c0\xb7\ubc84\ub514\xb7\uacfc\ud638\ud761 \uae08\uc9c0 \ub4f1 \uc548\uc804\uc218\uce59\uc744 \uc900\uc218\ud569\ub2c8\ub2e4.")
B.amH=new A.hi("health","\uac74\uac15 \uace0\uc9c0\xb7\uc758\ud559 \uc9c4\uc220\uc11c\uc5d0 \uc0ac\uc2e4\ub300\ub85c \uc751\ud558\uace0 \uc774\uc0c1 \uc2dc \uc989\uc2dc \uc911\ub2e8\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
B.amA=new A.hi("emergency","\uc758\uc2dd \uc18c\uc2e4 \ub4f1 \uc751\uae09 \uc2dc \uad6c\uc870\xb7\uc774\uc1a1 \uc870\uce58\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4.")
B.ZW=s([B.amF,B.amE,B.amH,B.rf,B.rh,B.amA,B.rg],t.OZ)
B.anb=new A.ra("freediving","\ud504\ub9ac\ub2e4\uc774\ube59 \uba74\ucc45","\ud504\ub9ac\ub2e4\uc774\ube59 \ucc45\uc784 \uba74\ucc45 \ubc0f \uc704\ud5d8 \uc778\uc9c0\xb7\uc218\uc6a9 \ub3d9\uc758\uc11c","FREEDIVING LIABILITY RELEASE AND ASSUMPTION OF RISK AGREEMENT","\ubcf8 \ub3d9\uc758\uc11c\ub294 APDI \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721, \ud6c8\ub828 \ubc0f \uad00\ub828 \ud65c\ub3d9\uc5d0 \ucc38\uac00\ud558\ub294 \uc0ac\ub78c\uc774 \uc228\ucc38\uae30 \uc7a0\uc218\uc758 \uc7a0\uc7ac\uc801 \uc704\ud5d8\uacfc \uc548\uc804\uc0c1 \uc758\ubb34\ub97c \ucda9\ubd84\ud788 \uc774\ud574\ud558\uace0 \uc790\ubc1c\uc801\uc73c\ub85c \ucc38\uac00\ud558\ub294\uc9c0 \ud655\uc778\ud558\uae30 \uc704\ud55c \ubb38\uc11c\uc785\ub2c8\ub2e4. \ubcf8\uc778\uc740 \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \uc544\ub798 \ub0b4\uc6a9\uc744 \ucda9\ubd84\ud788 \uc77d\uace0, \uc774\ud574\ub418\uc9c0 \uc54a\ub294 \uc0ac\ud56d\uc5d0 \ub300\ud574 \uc124\uba85\uc744 \uc694\uccad\ud560 \uae30\ud68c\uac00 \uc788\uc74c\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.","\ubcf8 \ub3d9\uc758\uc11c\ub294 \ubcc4\ub3c4\uc758 \uac74\uac15\uc9c4\uc220\uc11c, \uad50\uc721\uacc4\uc57d \ubc0f \uacfc\uc815\ubcc4 \uc548\uc804\uad50\uc721 \ud655\uc778\uc11c\ub97c \ub300\uccb4\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.",B.a0b,B.ZW)
B.ZK=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc774 \uc804\ubb38\uc801\uc778 \uc7a5\ube44\uc640 \ud638\ud761 \uae30\uccb4, \ubcf5\uc7a1\ud55c \ub2e4\uc774\ube59 \uacc4\ud68d \ubc0f \uac10\uc555\uc808\ucc28\ub97c \ud3ec\ud568\ud560 \uc218 \uc788\uc73c\uba70, \uc77c\ubc18 \ub808\ud06c\ub9ac\uc5d0\uc774\uc158 \ub2e4\uc774\ube59\ubcf4\ub2e4 \uc911\ub300\ud55c \uc704\ud5d8\uc774 \uc99d\uac00\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc704\ud5d8\uc774 \uc874\uc7ac\ud568\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.a0j=s(["\uac10\uc555\ubcd1 \ubc0f \ub3d9\ub9e5\uac00\uc2a4\uc0c9\uc804\uc99d\uc744 \ud3ec\ud568\ud55c \uc7a0\uc218 \uad00\ub828 \uc9c8\ud658","\uc758\ubb34 \uac10\uc555\uc5d0 \ub530\ub978 \uc989\uac01\uc801\uc778 \uc218\uba74 \ubcf5\uadc0\uc758 \uc81c\ud55c","\uac10\uc555\uacc4\ud68d\uc758 \uc624\ub958 \ub610\ub294 \uacc4\ud68d \uc774\ud589 \uc2e4\ud328\uc5d0 \ub530\ub978 \uc704\ud5d8","\uc0b0\uc18c \ub3c5\uc131, \uc800\uc0b0\uc18c\uc99d, \uace0\ud0c4\uc0b0\ud608\uc99d \ubc0f \uc9c8\uc18c\ub9c8\ucde8 \ub4f1\uc758 \uc0dd\ub9ac\uc801 \uc704\ud5d8","\ud638\ud761 \uae30\uccb4\uc758 \uc885\ub958\uc640 \uc0ac\uc6a9 \uc870\uac74\uc5d0 \ub300\ud55c \ud310\ub2e8 \uc624\ub958","\ub2e4\uc911 \uc2e4\ub9b0\ub354 \ubc0f \ubcf5\uc7a1\ud55c \ud638\ud761\xb7\ubd80\ub825 \uc7a5\ube44\uc758 \uc624\uc791\ub3d9","\ud638\ud761 \uae30\uccb4 \uacf5\uae09 \ubb38\uc81c \ubc0f \uae30\uccb4 \uad00\ub9ac\uc0c1\uc758 \uc624\ub958","\uae4a\uc740 \uc218\uc2ec, \uc800\uc628, \ud574\ub958 \ubc0f \uc81c\ud55c\ub41c \uc2dc\uc57c\uc5d0 \ub530\ub978 \uc704\ud5d8","\ud300 \ubd84\ub9ac, \uc758\uc0ac\uc18c\ud1b5 \uc2e4\ud328 \ubc0f \uc218\uc911 \ube44\uc0c1\uc0c1\ud669 \ub300\uc751\uc758 \uc5b4\ub824\uc6c0","\uc7a5\uc2dc\uac04 \uc218\uc911\ud65c\ub3d9\uc5d0 \ub530\ub978 \uc2e0\uccb4\uc801\xb7\uc815\uc2e0\uc801 \ud53c\ub85c","\uc804\ubb38 \uad6c\uc870\uc2dc\uc124\uacfc \uc7ac\uc555\uce58\ub8cc\uc2dc\uc124 \uc811\uadfc\uc758 \uc9c0\uc5f0"],t.s)
B.an9=new A.e4("\uc81c2\uc870. \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc758 \ud2b9\uc218 \uc704\ud5d8\uc5d0 \ub300\ud55c \uc778\uc9c0",B.ZK,B.a0j)
B.Zq=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc774 \uc801\uc808\ud55c \uc120\ud589 \uc790\uaca9, \uad50\uc721, \uacbd\ud5d8 \ubc0f \uc804\ubb38\uc801\uc778 \uac10\ub3c5\uc744 \uc694\uad6c\ud558\ub294 \ud65c\ub3d9\uc784\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc790\uc2e0\uc758 \uad50\uc721 \uc218\uc900\uacfc \uc790\uaca9 \ubc94\uc704\ub97c \ubc97\uc5b4\ub098\ub294 \ud65c\ub3d9\uc744 \uc218\ud589\ud558\uc9c0 \uc54a\uc73c\uba70, \ub2f4\ub2f9 \uac15\uc0ac\uc758 \uad50\uc721\uae30\uc900 \ubc0f \uc548\uc804\uc9c0\uce68\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\ud2b9\uc815 \ud14c\ud06c\ub2c8\uceec \uad50\uc721\uacfc\uc815\uc5d0 \ub4f1\ub85d\ud558\uac70\ub098 \ubcf8 \ub3d9\uc758\uc11c\uc5d0 \uc11c\uba85\ud558\uc600\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud574\ub2f9 \uc218\uc911\ud65c\ub3d9\uc744 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc218\ud589\ud560 \uc790\uaca9\uc774 \ubd80\uc5ec\ub418\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.an5=new A.e4("\uc81c3\uc870. \uc804\ubb38 \uad50\uc721\uacfc \ucc38\uac00 \uc790\uaca9",B.Zq,B.A)
B.Yb=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ud638\ud761 \uae30\uccb4\uc758 \uc885\ub958\uc640 \uc870\uc131 \ubc0f \uc801\uc6a9 \ud658\uacbd\uc774 \uc548\uc804\uc5d0 \uc911\ub300\ud55c \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc0ac\ud56d\uc774 \uc911\uc694\ud568\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.YA=s(["\ud638\ud761 \uae30\uccb4\uc758 \uc815\ud655\ud55c \uc2dd\ubcc4\uacfc \ubd84\uc11d","\ud638\ud761 \uae30\uccb4\uc640 \uacc4\ud68d\ub41c \uc0ac\uc6a9 \ud658\uacbd\uc758 \uc801\ud569\uc131 \ud655\uc778","\uc2e4\ub9b0\ub354 \ubc0f \ud638\ud761\uc7a5\ube44\uc5d0 \ub300\ud55c \uc810\uac80\uacfc \uad00\ub9ac","\ud638\ud761 \uae30\uccb4 \uacf5\uae09 \uc774\uc0c1\uc5d0 \ub300\ud55c \ube44\uc0c1\uacc4\ud68d","\ud300\uc6d0 \uac04 \uae30\uccb4 \ubc0f \uc7a5\ube44 \uc815\ubcf4\uc758 \uc0c1\ud638 \ud655\uc778","\uad50\uc721\uacfc\uc815\uc5d0 \uc801\ud569\ud55c \uc7a5\ube44 \uad6c\uc131\uacfc \uc0ac\uc804 \uc548\uc804\uc810\uac80"],t.s)
B.amK=new A.e4("\uc81c4\uc870. \ud638\ud761 \uae30\uccb4 \ubc0f \ud2b9\uc218\uc7a5\ube44\uc758 \uc704\ud5d8",B.Yb,B.YA)
B.a0w=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0\uc11c \uc0ac\uc804\uc5d0 \uc218\ub9bd\ub41c \ub2e4\uc774\ube59 \uacc4\ud68d\uacfc \uac10\uc555 \uc758\ubb34\ub97c \uc900\uc218\ud558\ub294 \uac83\uc774 \uc911\uc694\ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc218\uc911 \ud658\uacbd\uc758 \ubcc0\ud654, \uc7a5\ube44 \uc774\uc0c1 \ub610\ub294 \uac1c\uc778\uc758 \uc2e0\uccb4\uc801 \uc0c1\ud0dc\uc5d0 \ub530\ub77c \uc608\uc815\ub41c \ub2e4\uc774\ube59 \uacc4\ud68d\uc758 \ubcc0\uacbd\uc774\ub098 \uc911\ub2e8\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc74c\uc744 \uc778\uc815\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2f4\ub2f9 \uac15\uc0ac\uac00 \uc2b9\uc778\ud55c \uacc4\ud68d\uacfc \ube44\uc0c1\uc808\ucc28\ub97c \uc900\uc218\ud558\uba70, \uc784\uc758\ub85c \ub2e4\uc774\ube59 \uc218\uc2ec, \uc2dc\uac04 \ub610\ub294 \ud65c\ub3d9 \ubc94\uc704\ub97c \ud655\ub300\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.amV=new A.e4("\uc81c5\uc870. \uac10\uc555\uc808\ucc28 \ubc0f \ub2e4\uc774\ube59 \uacc4\ud68d",B.a0w,B.A)
B.a_1=s(["\ubcf8\uc778\uc740 \uae4a\uc740 \uc218\uc2ec, \uc758\ubb34 \uac10\uc555 \ub610\ub294 \ud2b9\uc218\ud55c \uc218\uc911 \ud658\uacbd\uc5d0\uc11c \uc989\uac01\uc801\uc778 \uc218\uba74 \ubcf5\uadc0\uac00 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub3d9\uad74, \ub09c\ud30c\uc120 \ub0b4\ubd80 \ub4f1 \ucc9c\uc7a5 \ud3d0\uc1c4 \ud658\uacbd\uc5d0\uc11c\uc758 \ub2e4\uc774\ube59\uc740 \ucd94\uac00\uc801\uc778 \uc804\ubb38 \uad50\uc721, \uc790\uaca9, \uc7a5\ube44 \ubc0f \uc548\uc804\uacc4\ud68d\uc744 \ud544\uc694\ub85c \ud558\uba70, \ud574\ub2f9 \uad50\uc721\uacfc\uc815\uc758 \ud5c8\uc6a9 \ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uc218\ud589\ud574\uc57c \ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc774\ub7ec\ud55c \ud658\uacbd\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \ube44\uc0c1\uc0c1\ud669\uc774 \uc77c\ubc18\uc801\uc778 \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\ubcf4\ub2e4 \ubcf5\uc7a1\ud55c \ub300\uc751\uc744 \uc694\uad6c\ud560 \uc218 \uc788\uc74c\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.amU=new A.e4("\uc81c6\uc870. \ud2b9\uc218 \ud658\uacbd\uacfc \uc218\uba74 \ubcf5\uadc0\uc758 \uc81c\ud55c",B.a_1,B.A)
B.YB=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc774 \ub192\uc740 \uc218\uc900\uc758 \uc2e0\uccb4\uc801\xb7\uc815\uc2e0\uc801 \uc900\ube44\ub97c \uc694\uad6c\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uac74\uac15\uc9c4\uc220\uc11c\uc5d0 \uc815\ud655\ud558\uac8c \uc751\ub2f5\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \uc758\ub8cc\uc804\ubb38\uac00\uc758 \ud3c9\uac00\ub97c \ubc1b\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uac74\uac15 \uc0c1\ud0dc, \ud53c\ub85c \ub610\ub294 \uc2ec\ub9ac\uc801 \uc2a4\ud2b8\ub808\uc2a4 \ub4f1\uc73c\ub85c \uc548\uc804\ud55c \ub2e4\uc774\ube59\uc774 \uc5b4\ub835\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uacbd\uc6b0 \uc774\ub97c \uc989\uc2dc \uc54c\ub9ac\uace0 \ud65c\ub3d9\uc744 \uc911\ub2e8\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.amJ=new A.e4("\uc81c7\uc870. \uac74\uac15 \uc0c1\ud0dc \ubc0f \uc2e0\uccb4\uc801 \uc900\ube44",B.YB,B.A)
B.a_W=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0\uc11c \ud300\uc6d0 \uac04\uc758 \ud611\ub825, \uc758\uc0ac\uc18c\ud1b5 \ubc0f \uc0c1\ud638 \uc548\uc804 \ud655\uc778\uc774 \uc911\uc694\ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c \uc0ac\ud56d\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.a0B=s(["\ub2f4\ub2f9 \uac15\uc0ac\uc640 \ud300\uc6d0\uc774 \uacf5\uc720\ud55c \ub2e4\uc774\ube59 \uacc4\ud68d\uc744 \uc900\uc218\ud569\ub2c8\ub2e4.","\ub2e4\uc774\ube59 \uc804 \uc7a5\ube44 \ubc0f \ud638\ud761 \uae30\uccb4 \ud655\uc778 \uc808\ucc28\uc5d0 \ucc38\uc5ec\ud569\ub2c8\ub2e4.","\uacc4\ud68d\ub41c \ud300 \uad6c\uc131\uacfc \uc218\uc911 \uc758\uc0ac\uc18c\ud1b5 \uccb4\uacc4\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.","\uc7a5\ube44 \uc774\uc0c1 \ub610\ub294 \uc704\ud5d8\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uc989\uc2dc \ud300\uc6d0\uacfc \uac15\uc0ac\uc5d0\uac8c \uc54c\ub9bd\ub2c8\ub2e4.","\uac1c\uc778\uc758 \ud310\ub2e8\uc73c\ub85c \uad50\uc721\ubc94\uc704 \ub610\ub294 \ub2e4\uc774\ube59 \uacc4\ud68d\uc744 \ud655\ub300\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc548\uc804\uc0c1 \ud544\uc694\ud558\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uacbd\uc6b0 \ub2e4\uc774\ube59 \uc911\ub2e8\uc744 \uc694\uccad\ud569\ub2c8\ub2e4."],t.s)
B.an8=new A.e4("\uc81c8\uc870. \ud300 \ub2e4\uc774\ube59 \ubc0f \uc548\uc804\uc9c0\uce68 \uc900\uc218",B.a_W,B.a0B)
